struct OptionalPrivateScope {
  template<typename T>
  static decltype(auto) Value(T&& opt) {
    return std::forward<T>(opt).Value();
  }

  template<typename T, typename F>
  static auto Map(T&& opt, F&& f)
      -> Optional<decltype(std::forward<F>(f)(std::forward<T>(opt).Value()))> {
    if (opt.HasValue()) { return std::forward<F>(f)(std::forward<T>(opt).Value()); }

    return NullOpt;
  }

  template<typename T, typename F,
           typename U = std::decay_t<decltype(std::declval<F>()(std::declval<T>().Value()))>>
  static auto Bind(T&& opt, F&& f) -> std::enable_if_t<IsOptional<U>::value, U> {
    if (opt.HasValue()) { return std::forward<F>(f)(std::forward<T>(opt).Value()); }

    return NullOpt;
  }

  template<typename T, typename F,
           std::enable_if_t<std::is_same<decltype(std::declval<F>()()), void>::value, int> = 0>
  static auto OrElse(T&& opt, F&& f) -> std::decay_t<T> {
    if (!opt.HasValue()) {
      std::forward<F>(f)();
      return NullOpt;
    }

    return std::forward<T>(opt);
  }

  template<typename T, typename F,
           std::enable_if_t<
               std::is_convertible<decltype(std::declval<F>()()), std::decay_t<T>>::value, int> = 0>
  static auto OrElse(T&& opt, F&& f) -> std::decay_t<T> {
    if (!opt.HasValue()) { return std::forward<F>(f)(); }

    return std::forward<T>(opt);
  }
};

template<>
struct MessageFormatTrait<std::string> {
  template<typename Code, typename... Args>
  static std::string Format(Code&& code, Args&&... args) {
    if (sizeof...(args) > 0) {
      std::stringstream res;

      res << code << ": ";
      ((res << args), ...);

      return res.str();
    } else {
      return code;
    }
  }
};

template<>
struct MessageFormatTrait<std::string_view> {
  template<typename Code>
  static std::string_view Format(Code&& code) {
    return code;
  }
};

struct JustPrivateScope {
  template<typename T>
  static decltype(auto) Value(T&& v) {
    return std::forward<T>(v).Value();
  }

  template<typename T, std::enable_if_t<IsMaybe<RemoveCVRef<T>>::value, int> = 0>
  static decltype(auto) StackedError(T&& v) {
    return std::forward<T>(v).StackedError();
  }

  template<typename T, std::enable_if_t<!IsMaybe<RemoveCVRef<T>>::value, int> = 0>
  static decltype(auto) StackedError(T&& v) {
    return JustTraits<RemoveCVRef<T>>::ValueNotFoundError(std::forward<T>(v));
  }
};

